import createPocketCore from './core.js';
const $=s=>document.querySelector(s), content=$('#content'), modal=$('#dialog');
const types=['Normal','Grass','Fire','Water','Electric','Bug','Flying','Psychic','Ghost'];
const roots=[1,4,7,25,133,10,16,129,63,92], chains=[[1,2,3],[4,5,6],[7,8,9],[25,26],[133,134,135,136],[10,11,12],[16,17,18],[129,130],[63,64,65],[92,93,94]];
const zones=['Clover Meadow','Whispering Grove','Summit Trail','Partner League'];
const key='pocket-partner-save-v1';let tab='home', core, get, name, action, message, storeSave, loadSave, pet, species, pausedByUser=false, installPrompt=null, previousHatch=-1;
const sprite=(id,cls='')=>`<img class="sprite ${cls}" src="assets/${String(id).padStart(3,'0')}.png" alt="${name(id)}" width="56" height="56">`;
const button=(label,a,x=0,cls='',disabled=false)=>`<button class="${cls}" data-action="${a}" data-arg="${x}" ${disabled?'disabled':''}>${label}</button>`;
const hours=s=>`${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`;
const bar=(label,value,max=100,cls='')=>`<div class="stat"><div class="stat-label"><span>${label}</span><span>${max===100?`${value}%`:`${value} / ${max}`}</span></div><div class="bar ${cls}" role="progressbar" aria-label="${label}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${max}"><i style="width:${Math.min(100,value/max*100)}%"></i></div></div>`;
function persist(){const effectivePause=get(32);action(7,pausedByUser?1:0);const data=storeSave();action(7,effectivePause);try{localStorage.setItem(key,data);$('#save-status').textContent='Saved on this device';}catch{$('#save-status').textContent='Save unavailable';$('#notice').textContent='Browser storage is unavailable. Export your save from Game & saves before leaving.';}}
function popup(html){$('#dialog-body').innerHTML=html;if(!modal.open)modal.showModal();}
function announce(){ $('#notice').textContent=message(); }
function setTab(t){tab=t;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===t));render();}
function activePause(){action(7,pausedByUser||document.hidden?1:0);core._pp_tick(Date.now()/1000);}
function welcome(){return `<div class="card welcome"><span class="eyebrow">EVERY ADVENTURE STARTS SMALL</span><h2>Who will grow with you?</h2><p class="muted">Choose your first egg. Your partner is waiting on the other side.</p><div class="starter-grid">${roots.slice(0,5).map((id,i)=>button(`${sprite(id)}<strong>${name(id)}</strong><small>${['Grass','Fire','Water','Electric','Normal'][i]}</small>`,0,i,'starter')).join('')}</div><div class="welcome-info"><span>01 · Set the clock & hatch your egg</span><span>02 · Train & find your first battle</span><span>03 · 72 awake hours + battle XP to evolve</span></div></div>`;}
function home(){
 const id=get(0),hatched=get(30)>=30,rest=get(31)||get(32),options=roots.map((r,i)=>`<option value="${i}" ${get(1)===i?'selected':''} ${pet(i,1)?'':'disabled'}>${name(pet(i,0))}${pet(i,1)?'':` · ${pet(i,2)} wins to unlock`}</option>`).join('');
 return `<div class="layout"><div><div class="selectline"><label for="partner-select">Your partner</label><select id="partner-select" ${get(16)?'disabled':''}>${options}</select></div><div class="device"><div class="device-head"><span>POCKET / 01</span><small>VIRTUAL PARTNER SYSTEM</small></div><div class="screen ${rest?'sleeping':''}"><div class="screen-top"><span>${hatched?`No. ${String(id).padStart(3,'0')} · ${name(id)}`:'A NEW BEGINNING'}</span><span>${hatched?`Lv. ${get(4)}`:'EGG'}</span></div>${hatched?sprite(id,'pet-sprite'):'<div class="egg" aria-label="An egg waiting to hatch">🥚</div>'}<p class="pet-caption">${get(32)?'PAUSED':get(31)?'SLEEPING · Z Z Z':!get(33)?'SET THE CLOCK TO BEGIN':!hatched?`HATCHING IN ${30-get(30)} SECONDS`:'A little stronger, every day.'}</p></div><div class="device-status"><b>${rest?'Ⅱ TIMER RESTING':'● AWAKE TIME'} · <span id="awake-time">${hours(get(7))}</span></b><span>${types[get(27)]} partner</span></div><div class="device-actions">${button('<span>◒</span>Feed',1,0,'',!hatched||rest||get(16))}${button('<span>✧</span>Clean',1,1,'',!hatched||rest||get(16))}${button('<span>♡</span>Play',1,2,'',!hatched||rest||get(16))}${button('<span>↗</span>Train',1,3,'',!hatched||rest||get(16))}</div></div><div class="actionline">${!get(33)?button('Set clock & hatch →',5,0,'primary'):button(get(31)?'Wake partner ☀':'Sleep ☾',6,0,'',!!get(16))}<button data-pause>${pausedByUser?'Resume ▶':'Pause Ⅱ'}</button><button class="primary" data-tab="battle" ${!hatched||rest?'disabled':''}>${get(16)?'Resume battle':'Find a battle'} →</button></div></div><aside><div class="card"><div class="cardtitle"><h3>A little everyday care</h3><span class="tag">${get(14)}/10 TRAINING</span></div>${bar('Fullness',get(11))}${bar('Happiness',get(12),100,'gold')}${bar('Freshness',get(13),100,'lime')}<p class="side-notes" style="margin:16px 0 0">Care is for enjoying your partner. Evolution depends only on awake time and battle XP.</p></div><div class="card evolve-card"><div class="cardtitle"><span class="eyebrow">THE NEXT CHAPTER</span><span class="tag">${get(26)?'EVOLUTION':'FULLY EVOLVED'}</span></div><div class="evo-track">${chains[get(1)].map((n,i)=>`${i?(get(1)===4&&i>1?'<span>/</span>':'<span>›</span>'):''}${sprite(n)}`).join('')}</div>${get(26)?`<h2>${get(10)?'Ready for something big.':'Good things take time.'}</h2><div class="stat-label"><span>Awake time</span><span>${hours(get(7))} / 72h</span></div><div class="bar lime"><i style="width:${Math.min(100,get(7)/get(9)*100)}%"></i></div>${bar('Battle XP',get(6),get(8),'gold')}${button(get(10)?'Evolve your partner ✦':'Growing at their own pace',4,0,'primary',!get(10)||rest||!!get(16))}<p class="side-notes">Sleep, pause, hidden tabs and closed games stop the timer. Each evolution stage needs 72 awake hours.</p>`:'<h2>Look how far you’ve come.</h2><p class="smalltext">Keep battling, meet more partners, and fill your field guide.</p>'}</div></aside></div>`;
}
function battle(){
 if(get(30)<30||!get(15))return `<div class="card"><h2>A partner comes first.</h2><p>Hatch your egg before setting out.</p><button data-tab="home" class="primary">Back to your partner →</button></div>`;
 if(get(16))return `<div class="layout"><div class="device"><div class="device-head"><span>${zones[get(24)].toUpperCase()}</span><small>TURN ${get(29)+1}</small></div><div class="screen battlefield"><div class="combatant"><div class="hpinfo"><strong>${name(get(17))}</strong>${bar('HP',get(20),get(21),'gold')}</div>${sprite(get(17))}</div><div class="versus">— VS —</div><div class="combatant">${sprite(get(0))}<div class="hpinfo"><strong>${name(get(0))} · Lv.${get(4)}</strong>${bar('HP',get(18),get(19))}</div></div><div class="pet-caption">FOCUS ${'●'.repeat(get(22))}${'○'.repeat(5-get(22))}</div></div><div class="moves">${button('Tackle <small>Steady hit · +1 focus</small>',3,0,'',!!get(32))}${button(`${types[get(27)]} burst <small>Type attack · costs 2 focus</small>`,3,1,'primary',get(22)<2||!!get(32))}${button('Guard <small>Reduce damage · +2 focus</small>',3,2,'',!!get(32))}${button('Healing berry <small>Restore HP · once per battle</small>',3,3,'',!get(23)||!!get(32))}</div></div><aside><div class="card"><span class="eyebrow">A LITTLE STRATEGY</span><h2>Make your next move.</h2><p class="smalltext">Use a type burst for a strong hit. Tackle builds focus. Guard softens the next attack, and a berry can turn things around.</p><p class="smalltext">Every completed battle earns evolution XP—even a loss. You return home healed.</p><p class="side-notes">Fire beats Grass and Bug. Water beats Fire. Grass beats Water. Electric beats Water and Flying. This game uses a simplified type chart.</p>${button('Return home',3,4,'',!!get(32))}</div><div class="card"><span class="eyebrow">YOUR RECORD</span><h2>${get(2)} wins · ${get(3)} losses</h2><p class="smalltext">Retreating awards no experience.</p></div></aside></div>`;
 const gates=[0,3,8,15];return `<div class="cardtitle"><div><span class="eyebrow">A NEW CHALLENGE AWAITS</span><h2>Pick your next adventure.</h2></div><span class="tag">${get(2)} WINS</span></div>${get(31)||get(32)?'<p>Your partner is resting. Wake or resume on the Partner screen to battle.</p>':''}<div class="zones">${zones.map((n,i)=>button(`<span class="num">ROUTE 0${i+1}</span><h3>${n}</h3><p>${['A gentle start. Meet small Pokémon and find your rhythm.','Stronger opponents among the trees. Bring a little strategy.','A bigger climb. Test your training against evolved partners.','The toughest partners. Make every move count.'][i]}</p><span class="tag">${get(2)<gates[i]?`UNLOCKS AT ${gates[i]} WINS`:`+${20+i*10} XP PER WIN →`}</span>`,2,i,'zone',get(2)<gates[i]||!!get(31)||!!get(32))).join('')}</div>`;
}
function collection(){let count=0,cells='';for(let i=0;i<get(28);i++){let id=species(i,0),seen=species(i,2);count+=seen;cells+=`<div class="dex-cell ${seen?'':'unknown'}"><small>No. ${String(id).padStart(3,'0')}</small>${sprite(id)}<strong>${seen?name(id):'Undiscovered'}</strong></div>`;}return `<div class="cardtitle"><div><span class="eyebrow">FAMILIAR FACES, NEW FRIENDS</span><h2>Your field guide.</h2></div><span class="tag">${count} / ${get(28)} DISCOVERED</span></div><p class="smalltext muted">Meet Pokémon in battles and through evolution. Wins unlock new partner eggs in the Partner selector. This release has 10 partner families and 32 discoverable Pokémon.</p><div class="collection-grid">${cells}</div>`;}
function settings(){return `<div class="settings-grid"><div class="card"><span class="eyebrow">KEEP YOUR ADVENTURE</span><h2>Your save, your device.</h2><p class="smalltext">Progress saves automatically in this browser. Export a backup to move between devices or the Windows app.</p><button id="export">Export save ↓</button><button id="import">Import save ↑</button><input hidden id="save-file" type="file" accept=".save,.txt"><p class="side-notes">Import replaces this device’s current progress after confirmation. Browser storage can be cleared by browser settings.</p></div><div class="card"><span class="eyebrow">TAKE IT WITH YOU</span><h2>Play offline.</h2><p class="smalltext" id="offline-status">${'serviceWorker' in navigator?'Preparing the offline game files…':'Use the Windows download for offline play in this browser.'}</p><button id="install-settings">Install on this device ↗</button><a class="download primary" href="https://github.com/agammann/pocket-partner/releases/latest/download/Pocket-Partner-Windows.zip">Download for Windows ↓</a><p class="side-notes">Windows: extract the ZIP and open Play.cmd. iPhone: Safari → Share → Add to Home Screen. Installation needs an initial download.</p></div><div class="card"><h3>How evolution works</h3><p class="smalltext">Set your local clock once. Eggs hatch after 30 active seconds. Every evolution needs 72 hours of awake, active time plus battle XP: 60 for the first stage and 160 for the next. Caterpie uses 20 and 40 XP.</p><p class="smalltext">Only your selected partner’s timer runs. Sleep, pause, hidden tabs, closed games and suspended devices do not count. You decide when to evolve. Eevee gives you three choices.</p></div><div class="card"><h3>Made for little breaks</h3><p class="smalltext">No death, care penalties to evolution, accounts, ads or purchases. Train up to 10 times per partner for extra attack strength. The core rules run in C++.</p><p class="smalltext"><a href="https://github.com/agammann/pocket-partner">Source, build instructions & releases ↗</a></p><button id="show-help">Credits & controls</button></div></div>`;}
function render(){if(!core)return;content.innerHTML=!get(15)&&tab==='home'?welcome():({home,battle,collection,settings}[tab])();if(tab==='settings')offlineStatus();}
function help(){popup(`<span class="eyebrow">POCKET PARTNER</span><h2>A small world to call your own.</h2><p>Created and published by <a href="https://github.com/agammann">agammann</a>. Inspired by virtual-pet care games and Pokémon’s battles and evolution families. No Tamaweb or DMWeb code or artwork is included.</p><p>Pokémon Yellow sprites archived by <a href="https://github.com/ShiraTheMogul/rby-sprites-project">The RBY Sprites Project</a> (Plague von Karma). Pokémon names and artwork belong to their respective rights holders. This is an unofficial fan project with no affiliation or endorsement.</p><p><b>Controls:</b> use touch or mouse; Tab and Enter work with all buttons. Battle actions happen one turn at a time. Your game saves after every action.</p><p><b>Evolution:</b> 72 active awake hours per stage and battle XP. Sleep or pause whenever you need. Care never blocks evolution.</p><button class="primary" data-close>Back to my adventure</button>`);}
async function offlineStatus(){const node=$('#offline-status');if(!node||!('serviceWorker' in navigator))return;try{await navigator.serviceWorker.ready;const keys=await caches.keys();node.textContent=keys.some(k=>k.startsWith('pocket-partner-'))?'Offline files downloaded. You can play without a connection on this device.':'Offline files are still downloading. Keep this page open until ready.';}catch{node.textContent='Offline setup is unavailable here. The Windows download works offline.';}}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else popup('<h2>Keep your partner close.</h2><p>On iPhone or iPad, open this game in Safari, then Share → Add to Home Screen.</p><p>On Android or desktop, use your browser’s Install app option. If it is already installed, open it from your home screen or app menu.</p><p>Wait until Game & saves shows that offline files are downloaded before disconnecting.</p>');}
document.addEventListener('click',async e=>{
const target=e.target.closest('button');if(!target||target.disabled||!core)return;
if(target.dataset.tab){setTab(target.dataset.tab);return;}if('pause' in target.dataset){pausedByUser=!pausedByUser;activePause();persist();render();return;}
if(target.dataset.action!==undefined){const a=+target.dataset.action,x=+target.dataset.arg;if(a===4&&get(0)===133&&target.dataset.branch===undefined){popup(`<h2>A new path for Eevee.</h2><p>Choose the partner you’ll become. This choice is permanent for this save.</p><div class="branch-picks">${[134,135,136].map((id,i)=>`<button data-action="4" data-arg="${i}" data-branch="1">${sprite(id)}${name(id)}</button>`).join('')}</div>`);return;}
 const changed=action(a,x);if(a===5)core._pp_tick(Date.now()/1000);if(changed&&a===2)tab='battle';if(changed&&a===3&&!get(16)){const msg=message();popup(`<span class="eyebrow">BATTLE COMPLETE</span><h2>${msg.startsWith('Victory')?'Nicely done, partner.':'Every battle helps you grow.'}</h2>${sprite(get(0),'evolved')}<p>${msg}</p><button class="primary" data-close>Keep adventuring →</button>`);}if(changed&&a===4)popup(`<span class="eyebrow">A NEW CHAPTER</span><h2>Your partner evolved!</h2>${sprite(get(0),'evolved')}<p>${message()}</p><button class="primary" data-close>Hello, ${name(get(0))} →</button>`);persist();setTab(tab);announce();return;
}
if(target.matches('.close,[data-close]'))modal.close();if(target.id==='credits'||target.id==='show-help')help();if(target.id==='install'||target.id==='install-settings')install();
if(target.id==='export'){const url=URL.createObjectURL(new Blob([storeSave()],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='Pocket-Partner.save';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
if(target.id==='import')$('#save-file').click();
});
document.addEventListener('change',async e=>{if(e.target.id==='partner-select'){action(0,+e.target.value);persist();render();announce();}if(e.target.id==='save-file'&&e.target.files[0]){const file=e.target.files[0];if(file.size>16000){popup('<h2>That save is too large.</h2><p>Choose a Pocket Partner .save file.</p>');return;}const text=await file.text();popup('<h2>Replace this device’s save?</h2><p>Export your current progress first if you want to keep it. This replaces the game on this device only.</p><button id="confirm-import" class="primary">Replace with imported save</button>');$('#confirm-import').onclick=()=>{if(loadSave(text)){pausedByUser=!!get(32);activePause();persist();modal.close();render();announce();}else popup('<h2>Could not read that save.</h2><p>Your current progress is unchanged. Choose an unmodified Pocket Partner save file.</p>');};}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});
document.addEventListener('visibilitychange',()=>{if(core){activePause();persist();render();}});
window.addEventListener('pagehide',()=>{if(core)persist();});
try{core=await createPocketCore();get=core.cwrap('pp_get','number',['number']);name=core.cwrap('pp_name','string',['number']);action=core.cwrap('pp_action','number',['number','number']);message=core.cwrap('pp_message','string',[]);storeSave=core.cwrap('pp_save','string',[]);loadSave=core.cwrap('pp_load','number',['string']);pet=core.cwrap('pp_pet','number',['number','number']);species=core.cwrap('pp_species','number',['number','number']);let badSave=false;try{const saved=localStorage.getItem(key);if(saved&&!loadSave(saved))badSave=true;}catch{}pausedByUser=!!get(32);activePause();$('#loading').textContent='';render();if(badSave){popup('<h2>Your save needs attention.</h2><p>The stored save could not be read. It has not been overwritten. Import a backup in Game & saves, or choose a partner to begin a new adventure.</p>');}else persist();announce();setInterval(()=>{core._pp_tick(Date.now()/1000);$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(get(30)!==previousHatch){previousHatch=get(30);if(tab==='home')render();}const awake=$('#awake-time');if(awake)awake.textContent=hours(get(7));},1000);setInterval(()=>{if(!badSave){persist();if(tab==='home'&&!modal.open&&!content.contains(document.activeElement))render();}},15000);
}catch(error){console.error(error);$('#loading').textContent='The game could not start. Reload the page, or download the Windows version from GitHub.';}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(()=>offlineStatus()).catch(()=>{});
